package com.travelbird.ai.service;
import com.travelbird.ai.entity.BackendAiJobStatus;import com.travelbird.ai.repository.AiRecommendationJobRepository;import com.travelbird.global.error.AiJobFailureCode;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class AiCallbackTimeoutWorker{private final AiRecommendationJobRepository jobs;private final Clock clock;private final int seconds;public AiCallbackTimeoutWorker(AiRecommendationJobRepository jobs,Clock clock,@Value("${app.ai.callback-timeout-seconds:180}")int seconds){this.jobs=jobs;this.clock=clock;this.seconds=seconds;}@Scheduled(fixedDelayString="${app.ai.timeout-scan-delay-ms:10000}")@Transactional public void failTimedOutJobs(){var now=LocalDateTime.now(clock);for(var job:jobs.findByStatusAndStartedAtLessThanEqual(BackendAiJobStatus.PROCESSING,now.minusSeconds(seconds))){job.fail(AiJobFailureCode.AI_CALLBACK_TIMEOUT,"AI callback was not received within "+seconds+" seconds",true,now);}}}
